import java.util.Map;
import java.util.Scanner;

public class RecursiveCalculation {
    private static Map<Long, Long> cache = new HashMap<>();

    public static long recursiveCalc(long n) {
        if (cache.containsKey(n)) {
            return cache.get(n);
        }
        if (n <= 11) {
            long result = Math.min(n, 2 + (11 - n));
            cache.put(n, result);
            return result;
        }
        long pattern = 1;
        int level = 1;
        while (pattern <= n) {
            pattern = pattern * 10 + 1;
            level++;
        }
        long threshold = pattern / 10;
        long val1, val2;
        if (pattern > 2 * n) {
            long quotient = n / threshold;
            long remainder = n % threshold;
            val1 = recursiveCalc(pattern - n) + level;
            val2 = quotient * (level - 1) + recursiveCalc(remainder);
            long result = Math.min(val1, val2);
            cache.put(n, result);
            return result;
        } else {
            long quotient = n / threshold;
            long remainder = n % threshold;
            val1 = recursiveCalc(pattern - n) + level;
            val2 = quotient * (level - 1) + recursiveCalc(remainder);
            long result = Math.min(val1, val2);
            cache.put(n, result);
            return result;
        }
    }

    public static void main(String[] args) {
